const JS="\n(function(){\n  var header=document.querySelector('.site-header');\n  var progress=document.querySelector('.progress');\n  function onScroll(){\n    var y=window.scrollY||0;\n    if(header)header.classList.toggle('scrolled',y>20);\n    if(progress){\n      var h=document.documentElement.scrollHeight-innerHeight;\n      progress.style.width=(h>0?(y/h)*100:0)+'%';\n    }\n  }\n  addEventListener('scroll',onScroll,{passive:true});onScroll();\n  var menu=document.querySelector('.menu-button');\n  var nav=document.querySelector('.nav-links');\n  if(menu&&nav){\n    menu.addEventListener('click',function(){\n      var open=nav.classList.toggle('open');\n      menu.setAttribute('aria-expanded',String(open));\n    });\n    nav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')})});\n  }\n  var reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var reveals=document.querySelectorAll('.reveal');\n  if(!reduced&&'IntersectionObserver' in window){\n    var obs=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}})},{threshold:.12});\n    reveals.forEach(function(el){obs.observe(el)});\n  }else{reveals.forEach(function(el){el.classList.add('visible')})}\n  var tabs=document.querySelectorAll('.showcase-tab');\n  tabs.forEach(function(tab){\n    tab.addEventListener('click',function(){\n      tabs.forEach(function(t){t.classList.remove('active');t.setAttribute('aria-selected','false')});\n      document.querySelectorAll('.showcase-panel').forEach(function(p){p.classList.remove('active')});\n      tab.classList.add('active');tab.setAttribute('aria-selected','true');\n      var panel=document.getElementById(tab.getAttribute('aria-controls'));\n      if(panel)panel.classList.add('active');\n    });\n  });\n  document.querySelectorAll('.faq-q').forEach(function(btn){\n    btn.addEventListener('click',function(){\n      var item=btn.parentElement;var open=item.classList.toggle('open');\n      btn.setAttribute('aria-expanded',String(open));\n    });\n  });\n  var stage=document.querySelector('.product-stage');\n  var win=document.querySelector('.app-window');\n  if(stage&&win&&!reduced&&matchMedia('(pointer:fine)').matches){\n    stage.addEventListener('pointermove',function(e){\n      var r=stage.getBoundingClientRect();\n      var x=(e.clientX-r.left)/r.width-.5;var y=(e.clientY-r.top)/r.height-.5;\n      win.style.transform='rotateY('+(-5+x*5)+'deg) rotateX('+(2-y*4)+'deg) translate3d('+(x*4)+'px,'+(y*4)+'px,0)';\n    });\n    stage.addEventListener('pointerleave',function(){win.style.transform='rotateY(-5deg) rotateX(2deg)'});\n  }\n})();\n";
